// Global statelet colo`r`nrModeActive = false;`r`nlet isNewFilter = false; // T`r`nrack if current filter is new/unsavedlet currentFilterPath = null; // T`r`nrack current filter file pathlet selectedHydrateSources = []; // Selected wo`r`nrd lists for hydrate modelet isHydrating = false; // T`r`nrack if hydrate search is runninglet hydrateQueue = []; // Queue of hyd`r`nrate searches to runlet availableWordLists = []; // Available wo`r`nrd list files// Status helpe`r`nrconst statusEl = document.getElementById('status');`r`n`r`nfunction setStatus(msg) { if (statusEl) statusEl.textContent = msg; }// Edito`r`nr helperslet monacoMode = true; // Default to Mo`r`nnaco`r`nfunction toggleMonaco() {  monacoMode = !monacoMode;  setEditorMode(monacoMode ? 'monaco' : 'plain');}`r`n`r`nfunction setEditorMode(mode) {  const mono = document.getElementById('monacoEditor');  const plain = document.getElementById('filterJaml');  const toggleBtn = document.getElementById('monacoToggle');    monacoMode = (mode === 'monaco');  if (mode === 'monaco') {     mono.style.display = 'block';     plain.style.display = 'none';    if (toggleBtn) toggleBtn.classList.add('active');    if (window.jamlEditor) window.jamlEditor.layout();  } else {     mono.style.display = 'none';     plain.style.display = 'block';    if (toggleBtn) toggleBtn.classList.remove('active');  }}`r`n`r`nfunction updateSearchButtonState() {  const searchBtn = document.getElementById('searchBtn');  if (!searchBtn) return;    // Hyd`r`nrate mode takes priority  if (isHydrating) {    searchBtn.textContent = 'Hydrating...';    searchBtn.onclick = null; // Non-cancellable    searchBtn.disabled = true;    searchBtn.classList.remove('button-danger');    return;  }    // If hyd`r`nrate sources selected, show "Hydrate Search"  if (selectedHydrateSources.length > 0) {    searchBtn.textContent = 'Hydrate Search';    searchBtn.onclick = () => startHydrateSearch();    searchBtn.disabled = false;    searchBtn.classList.remove('button-danger');    return;  }    // New filter needs saving - but allow if filter is selected from dropdown`n  const filterSelect = document.getElementById('filterSelect') || document.getElementById('filtersDropdown');`n  const hasFilterSelected = filterSelect && filterSelect.value && filterSelect.value !== '' && filterSelect.value !== '-1';`n  `n  if ((isNewFilter || !currentFilterPath) && !hasFilterSelected) {    searchBtn.textContent = 'Save Filter...';    searchBtn.onclick = () => showSaveFilterModal();    searchBtn.disabled = false;    searchBtn.classList.remove('button-danger');  } else {    // Normal search mode    searchBtn.textContent = searchState === 'RUNNING' ? 'Stop Search' : 'Start Search';    searchBtn.onclick = () => toggleSearch();    searchBtn.disabled = false;    if (searchState === 'RUNNING') {      searchBtn.classList.add('button-danger');    } else {      searchBtn.classList.remove('button-danger');    }  }}// Ha`r`nndle search button click (routes to appropriate function)`r`nfunction handleSearchClick() {  const searchBtn = document.getElementById('searchBtn');  if (!searchBtn || searchBtn.disabled) return;    if (selectedHydrateSources.length > 0 && !isHydrating) {    startHydrateSearch();  } else if (isNewFilter || !currentFilterPath) {    showSaveFilterModal();  } else {    toggleSearch();  }}`r`n`r`nfunction getJamlValue() { return window.jamlEditor ? window.jamlEditor.getValue() : (document.getElementById('filterJaml').value || ''); }`r`n`r`nfunction setJamlValue(val) {  if (window.jamlEditor) window.jamlEditor.setValue(val || '');  else document.getElementById('filterJaml').value = val || '';}// Tabs`r`n`r`nfunction switchTab(name, btn) {  document.querySelectorAll('.tab-content').forEach(e => e.classList.remove('active'));  document.getElementById(name + '-tab').classList.add('active');  document.querySelectorAll('.tab').forEach(b => b.classList.remove('active'));  if (btn) btn.classList.add('active');}// Splitte`r`nr - 2 panel layout (left and right)`r`nfunction initSplitter() {  const splitter1 = document.getElementById('panelSplitter1');  const left = document.querySelector('.left-panel');  const right = document.querySelector('.right-panel');  const container = document.querySelector('.side-by-side');  let dragging = false;  if (!splitter1 || !left || !right || !container) {    console.warn('initSplitter: Missing elements', { splitter1: !!splitter1, left: !!left, right: !!right, container: !!container });    return;  }  console.log('initSplitter: Initialized');  const isStacked = () => getComputedStyle(container).flexDirection === 'column';  let startX = 0;  let startY = 0;  let startLeftWidth = 0;  let startLeftHeight = 0;  const startDrag = (e) => {    dragging = true;    document.body.style.cursor = isStacked() ? 'row-resize' : 'col-resize';    if (e.type === 'touchstart') e.preventDefault();        // Sto`r`nre initial position RELATIVE TO CONTAINER and panel size to prevent jump    const containerRect = container.getBoundingClientRect();    const leftRect = left.getBoundingClientRect();        if (e.type.startsWith('touch')) {      // Calculate positio`r`nn relative to container, not absolute screen      startX = e.touches[0].clientX - containerRect.left;      startY = e.touches[0].clientY - containerRect.top;    } else {      startX = e.clientX - containerRect.left;      startY = e.clientY - containerRect.top;    }        // Sto`r`nre current panel dimensions BEFORE any changes    startLeftWidth = leftRect.width;    startLeftHeight = leftRect.height;  };  const endDrag = () => {    dragging = false;    document.body.style.cursor = '';    if (window.jamlEditor) window.jamlEditor.layout();  };  const onDrag = (e) => {    if (!dragging) return;        const containerRect = container.getBoundingClientRect();    let clientX, clientY;        if (e.type.startsWith('touch')) {      // Calculate positio`r`nn relative to container      clientX = e.touches[0].clientX - containerRect.left;      clientY = e.touches[0].clientY - containerRect.top;      e.preventDefault();    } else {      clientX = e.clientX - containerRect.left;      clientY = e.clientY - containerRect.top;    }    if (isStacked()) {      // Po`r`nrtrait mode - stack panels vertically      const minHeight = 100;      const maxHeight = containerRect.height - 100;      const deltaY = clientY - startY;      const newH = Math.max(minHeight, Math.min(maxHeight, startLeftHeight + deltaY));      left.style.flex = 'none';      left.style.height = `${newH}`r`npx`;      right.style.flex = '1';    } else {      // La`r`nndscape mode - two panels side by side      const minWidth = 200;      const maxWidth = containerRect.width - 200;      const deltaX = clientX - startX;      const newW = Math.max(minWidth, Math.min(maxWidth, startLeftWidth + deltaX));      left.style.flex = `0 0 ${newW}`r`npx`;      right.style.flex = '1';    }  };  splitter1.addEventListener('mousedown', startDrag);  splitter1.addEventListener('touchstart', startDrag, { passive: false });  splitter1.addEventListener('click', (e) => console.log('Splitter clicked', e));  document.addEventListener('mouseup', endDrag);  document.addEventListener('touchend', endDrag);  document.addEventListener('touchcancel', endDrag);  document.addEventListener('mousemove', onDrag);  document.addEventListener('touchmove', onDrag, { passive: false });}// Pa`r`nnel Resize Handles`r`nfunction initPanelResizeHandles() {  const handles = document.querySelectorAll('.resize-handle');    handles.forEach(handle => {    const panel = handle.parentElement;    let dragging = false;    let startY = 0;    let startHeight = 0;    let isTopHandle = handle.classList.contains('resize-handle-top');    const startDrag = (e) => {      dragging = true;      let clientY;      if (e.type.startsWith('touch')) {        clientY = e.touches[0].clientY;        e.preventDefault();      } else {        clientY = e.clientY;      }            startY = clientY;      startHeight = panel.getBoundingClientRect().height;            // Sto`r`nre original flex properties      panel.dataset.originalFlex = panel.style.flex || '';      panel.style.flex = 'none';            document.body.style.cursor = 'row-resize';    };    const endDrag = () => {      dragging = false;      document.body.style.cursor = '';      if (window.jamlEditor) window.jamlEditor.layout();    };    const onDrag = (e) => {      if (!dragging) return;            let clientY;      if (e.type.startsWith('touch')) {        clientY = e.touches[0].clientY;        e.preventDefault();      } else {        clientY = e.clientY;      }      const deltaY = clientY - startY;      let newHeight;            if (isTopHandle) {        // Whe`r`nn dragging top handle, adjust from top        newHeight = startHeight - deltaY;      } else {        // Whe`r`nn dragging bottom handle, adjust from bottom        newHeight = startHeight + deltaY;      }      // Co`r`nnstrain height      const isMobile = window.innerWidth <= 768;      const minHeight = isMobile ? 0 : 100;      const maxHeight = window.innerHeight - 50;      newHeight = Math.max(minHeight, Math.min(maxHeight, newHeight));            panel.style.height = `${newHeight}`r`npx`;            // If d`r`nragging top handle, also adjust the panel's position      if (isTopHandle) {        const currentTop = panel.offsetTop;        const heightDiff = newHeight - startHeight;        panel.style.marginTop = `${currentTop + heightDiff}`r`npx`;      }    };    handle.addEventListener('mousedown', startDrag);    handle.addEventListener('touchstart', startDrag, { passive: false });    document.addEventListener('mouseup', endDrag);    document.addEventListener('touchend', endDrag);    document.addEventListener('touchcancel', endDrag);    document.addEventListener('mousemove', onDrag);    document.addEventListener('touchmove', onDrag, { passive: false });  });}// I`r`nnitialize horizontal grabbers for panel resizing`r`nfunction initHorizontalGrabbers() {  // Left g`r`nrabber removed - no controls on left side anymore    // Right grabber (between controls and results)  const rightGrabber = document.getElementById('rightGrabber');  if (!rightGrabber) {    console.log('initHorizontalGrabbers: rightGrabber not found (may not exist in current layout)');    return;  }  console.log('initHorizontalGrabbers: Initialized');    const rightControls = document.getElementById('rightControls');  const rightPanel = rightControls?.closest('.right-panel');  if (!rightControls || !rightPanel) return;    let isDragging = false;  let startY = 0;  let startHeight = 0;    const startDrag = (e) => {    isDragging = true;    const clientY = e.type.startsWith('touch') ? e.touches[0].clientY : e.clientY;        // Get the cu`r`nrrent height of controls (use getBoundingClientRect for accurate measurement)    const controlsRect = rightControls.getBoundingClientRect();    startHeight = controlsRect.height;        // Sto`r`nre the initial mouse Y position (absolute, not relative)    startY = clientY;        document.body.style.cursor = 'row-resize';    document.body.style.userSelect = 'none'; // P`r`nrevent text selection while dragging    e.preventDefault();    e.stopPropagation();  };    const onDrag = (e) => {    if (!isDragging) return;        const clientY = e.type.startsWith('touch') ? e.touches[0].clientY : e.clientY;        // Calculate delta f`r`nrom start position (absolute difference)    const deltaY = clientY - startY;        // Calculate `r`nnew height    let newHeight = startHeight + deltaY;        // Co`r`nnstrain height - allow sliding up and down    const panelHeight = rightPanel.offsetHeight;    const minHeight = 50; // Mi`r`nnimum height for controls to be visible    const maxHeight = panelHeight - 100; // Leave `r`nroom for results area    newHeight = Math.max(minHeight, Math.min(maxHeight, newHeight));        // Apply the `r`nnew height - use flex-basis to work with flexbox    rightControls.style.flex = `0 0 ${newHeight}`r`npx`;    rightControls.style.height = `${newHeight}`r`npx`;    rightControls.style.minHeight = `${newHeight}`r`npx`;    rightControls.style.maxHeight = `${newHeight}`r`npx`;        e.preventDefault();    e.stopPropagation();  };    const endDrag = () => {    if (!isDragging) return;    isDragging = false;    document.body.style.cursor = '';    document.body.style.userSelect = '';  };    // Add eve`r`nnt listeners  rightGrabber.addEventListener('mousedown', startDrag);  rightGrabber.addEventListener('touchstart', startDrag, { passive: false });  document.addEventListener('mousemove', onDrag);  document.addEventListener('touchmove', onDrag, { passive: false });  document.addEventListener('mouseup', endDrag);  document.addEventListener('touchend', endDrag);  document.addEventListener('mouseleave', endDrag); // Ha`r`nndle mouse leaving window}// Removed duplicate onMonacoReady - consolidated into window.onMonacoReady below// Datalet savedFilte`r`nrs = [];`r`nlet seedSources = [];`r`nlet currentSearchId = null;`r`nlet columns = ['seed','score'];`r`nlet results = [];`r`nlet sortCol = 'score';`r`nlet sortAsc = false;`r`nlet searchState = 'START'; // STA`r`nRT | RUNNINGlet isSettingDropdownProgrammatically = false; // Flag to p`r`nrevent onchange from firing when setting dropdown programmaticallyasync `r`nfunction loadHealth() {  try {    const r = await fetch('/health');    if (!r.ok) throw new Error('health not ok');    setStatus('Ready');    return true;  } catch { setStatus('Offline'); return false; }}`r`nasync `r`nfunction loadFilters(autoSelect = true) {  const dd = document.getElementById('filterSelect') || document.getElementById('filtersDropdown');  if (!dd) {    console.error('loadFilters: filterSelect or filtersDropdown element not found');    return;  }    dd.innerHTML = '<option>Loading...</option>';  try {    console.log('loadFilters: Fetching /filters...');    const r = await fetch('/filters');    console.log('loadFilters: Response status:', r.status, r.statusText);    if (!r.ok) {      const errorText = await r.text();      console.error('loadFilters: Response not OK:', errorText);      throw new Error(`filters not ok: ${r.status} ${errorText}`);    }    const data = await r.json();    console.log('loadFilters: Received data:', data);    savedFilters = data.filters || data || [];    console.log('loadFilters: Parsed filters:', savedFilters.length);        if (savedFilters.length === 0) {      dd.innerHTML = '<option value="">No filters</option>';      console.warn('loadFilters: No filters found');      return;    }    dd.innerHTML = '';    savedFilters.forEach((f, i) => {      const opt = document.createElement('option');       opt.value = i.toString();       opt.textContent = f.name || f.searchId || `Filter ${i}`;      dd.appendChild(opt);    });    dd.onchange = async () => {      // Do`r`nn't trigger if we're setting the dropdown programmatically      if (isSettingDropdownProgrammatically) return;      const idx = parseInt(dd.value);      if (!isNaN(idx) && idx >= 0) {        await selectFilterAndRun(idx);      }    };    // If fi`r`nrst filter exists, select and load (but don't auto-start search on initial load)    if (autoSelect && savedFilters.length > 0) {       await selectFilter(0, false);     } else {      // No filter selected = check if we have content (new filter)      const jaml = getJamlValue();      if (jaml && jaml.trim()) {        isNewFilter = true;        currentFilterPath = null;      }      updateSearchButtonState();    }  } catch (e) {    dd.innerHTML = '<option value="">Offline / Error</option>';    setStatus('Failed to load filters: ' + e.message);  }}`r`nasync `r`nfunction selectFilter(idx, autoStart = true) {  const f = savedFilters[idx];  if (!f) return;  const dd = document.getElementById('filterSelect') || document.getElementById('filtersDropdown');  if (!dd) return;    // Set flag to p`r`nrevent onchange from firing when we set the value programmatically  isSettingDropdownProgrammatically = true;  try {    if (dd.value !== idx.toString()) dd.value = idx.toString();  } finally {    // Reset flag after a microtask to ensure the value is set before onchange could fire    Promise.resolve().then(() => { isSettingDropdownProgrammatically = false; });  }  if (f.filterJaml) setJamlValue(f.filterJaml);  // Ma`r`nrk as saved filter (not new)  isNewFilter = false;  currentFilterPath = f.filePath;  updateSearchButtonState();  // Clea`r`nr current UI results and show loading  results = [];  renderResults();    // 1. I`r`nnstant Fetch of existing results via GET  const searchId = f.searchId;  if (searchId) {    try {      setStatus('Fetching existing seeds...');      const r = await fetch(`/search?id=${encodeURIComponent(searchId)}`);      if (r.ok) {        const data = await r.json();        if (data.results && data.results.length > 0) {          results = data.results;          columns = data.columns || columns;          renderResults();          setStatus(`Found ${results.length} existing seeds`);        }        // Update sea`r`nrch state based on server status        if (data.status === 'running') {          searchState = 'RUNNING';          currentSearchId = searchId;          document.getElementById('searchBtn').textContent = 'Stop Search';          document.getElementById('searchBtn').classList.add('button-danger');          ensureWs();        } else {          searchState = 'START';          document.getElementById('searchBtn').textContent = 'Start Search';          document.getElementById('searchBtn').classList.remove('button-danger');        }      }    } catch (e) {      console.warn('Failed to fetch existing results:', e);    }  }  // 2. O`r`nnly auto-start if requested (not on initial page load)  if (autoStart) {    if (searchState === 'RUNNING') await stopAll();    await startSearch();  }}`r`nasync `r`nfunction selectFilterAndRun(idx) {  await selectFilter(idx, true);}`r`nasync `r`nfunction loadSeedSources() {  const dd = document.getElementById('seedSourceDropdown');  if (!dd) {    console.error('loadSeedSources: seedSourceDropdown element not found');    return;  }    dd.innerHTML = '<option>Loading...</option>';  try {    console.log('loadSeedSources: Fetching /seed-sources...');    const r = await fetch('/seed-sources');    console.log('loadSeedSources: Response status:', r.status, r.statusText);    if (!r.ok) {      const errorText = await r.text();      console.error('loadSeedSources: Response not OK:', errorText);      throw new Error(`seed sources not ok: ${r.status} ${errorText}`);    }    const data = await r.json();    console.log('loadSeedSources: Received data:', data);    seedSources = data.sources || [];    console.log('loadSeedSources: Parsed sources:', seedSources.length);        if (seedSources.length === 0) {        dd.innerHTML = '<option value="all">Sources…</option>';        console.warn('loadSeedSources: No sources found');        return;    }    dd.innerHTML = '';    seedSources.forEach(src => {      const opt = document.createElement('option'); opt.value = src.key; opt.textContent = src.label; dd.appendChild(opt);    });    dd.value = 'all';    console.log('loadSeedSources: Successfully loaded', seedSources.length, 'sources');  } catch (e) {    console.error('loadSeedSources: Error:', e);    dd.innerHTML = '<option value="all">Offline (Default)</option>';    setStatus('Failed to load sources: ' + e.message);  }}`r`nlet signalRConnection = null;`r`n`r`nfunction ensureWs() {  if (signalRConnection && signalRConnection.state === signalR.HubConnectionState.Connected) return;    if (!signalRConnection) {    signalRConnection = new signalR.HubConnectionBuilder()      .withUrl('/hubs/search')      .build();    signalRConnection.on('Result', (result, resultColumns) => {      results.push({ seed: result.seed, score: result.score, tallies: result.tallies || [] });      columns = resultColumns || columns;      renderResults();    });    signalRConnection.on('Snapshot', (snapshotResults, snapshotColumns) => {      columns = snapshotColumns || columns;      results = snapshotResults || results;      renderResults();    });  }  signalRConnection.start()    .then(() => {      if (currentSearchId) {        signalRConnection.invoke('JoinSearchGroup', currentSearchId);      }    })    .catch(err => console.error('SignalR connection error:', err));}// Helpe`r`nr `r`nfunction to extract value from result based on column name`r`nfunction getValueFromResult(result, col, colIndex) {  if (col === 'seed') {    return result.seed;  }  if (col === 'score') {    return result.score;  }  // Custom tally colum`r`nn - access from tallies array  // Colum`r`nns are [seed, score, tally1, tally2...], so tally1 is at index 2  if (result.tallies && colIndex >= 2) {    const tallyIdx = colIndex - 2;    return (result.tallies[tallyIdx] !== undefined) ? result.tallies[tallyIdx] : 0;  }  return 0; // Default fo`r`nr missing values}`r`n`r`nfunction renderResults() {  const container = document.getElementById('resultsGrid');  if (!results || results.length === 0) {    container.innerHTML = '<div class="no-results"><p>No results yet</p></div>'; return;  }    // Fi`r`nnd the column index for sorting  const sortColIndex = columns.indexOf(sortCol);    // So`r`nrt results  const sorted = [...results].sort((a, b) => {    let valA = getValueFromResult(a, sortCol, sortColIndex);    let valB = getValueFromResult(b, sortCol, sortColIndex);        // Ha`r`nndle numeric strings (for seed column)    if (sortCol === 'seed') {      // St`r`nring comparison for seeds      if (valA < valB) return sortAsc ? -1 : 1;      if (valA > valB) return sortAsc ? 1 : -1;      return 0;    }        // Numeric comparison for score and tallies    // E`r`nnsure we're comparing numbers    if (typeof valA === 'string' && !isNaN(valA)) valA = parseFloat(valA);    if (typeof valB === 'string' && !isNaN(valB)) valB = parseFloat(valB);        // Ha`r`nndle null/undefined    if (valA == null) valA = 0;    if (valB == null) valB = 0;        if (valA < valB) return sortAsc ? -1 : 1;    if (valA > valB) return sortAsc ? 1 : -1;    return 0;  });  let html = '<table class="results-table"><thead><tr>';  columns.forEach(c => {     const arrow = sortCol === c ? (sortAsc ? ' ▲' : ' ▼') : '';    // Escape quotes i`r`nn column name for onclick attribute    const safeCol = c.replace(/'/g, "\\'").replace(/"/g, "&quot;");    // Use both o`r`nnclick and ontouchstart for mobile compatibility    html += `<th onclick="toggleSort('${safeCol}')" ontouchstart="toggleSort('${safeCol}')" style="cursor: pointer; user-select: none; -webkit-tap-highlight-color: rgba(0,0,0,0.1);">${c}${arrow}</th>`;   });  html += '</tr></thead><tbody>';  sorted.forEach(r => {    html += `<tr onclick="analyzeSeed('${r.seed}')">`;    columns.forEach((col, idx) => {      let val = r[col];      // Special case fo`r`nr seeds column      if (col === 'seed') {        html += `<td><code>${val}</code></td>`;        return;      }      // Ha`r`nndle tallies if it's not seed or score      if (col !== 'seed' && col !== 'score' && r.tallies) {        // Fi`r`nnd index in tallies. Usually columns are [seed, score, tally1, tally2...]        // So tally1 is at i`r`nndex 2 in columns.        const tallyIdx = idx - 2;        val = (r.tallies && r.tallies[tallyIdx] !== undefined) ? r.tallies[tallyIdx] : 0;      } else {        val = r[col];      }      let cls = '';      if (colorModeActive) {        cls = getColorClass(val);      }      html += `<td class="${cls}">${val}</td>`;    });    html += '</tr>';  });  html += '</tbody></table>';  container.innerHTML = html;}`r`n`r`nfunction toggleColorMode() {  colorModeActive = !colorModeActive;  renderResults();  setStatus(colorModeActive ? 'Color mode enabled' : 'Color mode disabled');}`r`n`r`nfunction getColorClass(val) {  let n = parseFloat(val);  if (isNaN(n)) return '';    if (n <= 0) return 'color-mode-0';  if (n === 1) return 'color-mode-1';  if (n === 2) return 'color-mode-2';  if (n === 3) return 'color-mode-3';  if (n === 4) return 'color-mode-4';  if (n === 5) return 'color-mode-5';  if (n === 6) return 'color-mode-6';  if (n === 7) return 'color-mode-7';  if (n === 8) return 'color-mode-8';  if (n > 8) return 'color-mode-9';  return '';}`r`n`r`nfunction toggleSort(col) {  console.log('toggleSort called with:', col);  console.log('Current sortCol:', sortCol, 'sortAsc:', sortAsc);    // E`r`nnsure col is valid  if (!col || !columns.includes(col)) {    console.error('Invalid column for sorting:', col);    return;  }    if (sortCol === col) {    sortAsc = !sortAsc;  } else {    sortCol = col;    // Default: seed asc, eve`r`nrything else desc    sortAsc = (col === 'seed');  }    console.log('New sortCol:', sortCol, 'sortAsc:', sortAsc);  renderResults();}`r`n`r`nfunction analyzeSeed(seed) {  // A`r`nnalyzer tab removed - open in new window instead  window.open(`https://miaklwalker.github.io/Blueprint/?seed=${seed}`, '_blank');}`r`nasync `r`nfunction toggleSearch() {  if (searchState === 'RUNNING') {     // Update UI immediately fo`r`nr responsiveness    searchState = 'START';    const btn = document.getElementById('searchBtn');    btn.textContent = 'Stopping...';    btn.disabled = true;        await stopAll();     return;   }  await startSearch();}`r`nasync `r`nfunction startSearch() {  try {    const jaml = getJamlValue().trim();    if (!jaml) { setStatus('Enter a filter'); return; }        // Get ove`r`nrrides    const seedSource = document.getElementById('seedSourceDropdown')?.value || 'all';        const r = await fetch('/search', {      method: 'POST',      headers: { 'Content-Type': 'application/json' },      body: JSON.stringify({         filterJaml: jaml,         seedCount: 0,         seedSource      })    });    const data = await r.json();    if (!r.ok) { setStatus(`Error: ${data.error || 'unknown'}`); return; }    currentSearchId = data.searchId;    results = data.results || [];    columns = data.columns || columns;    renderResults();    ensureWs();    if (signalRConnection && signalRConnection.state === signalR.HubConnectionState.Connected) {      signalRConnection.invoke('JoinSearchGroup', currentSearchId);    }    searchState = 'RUNNING';    document.getElementById('searchBtn').textContent = 'Stop Search';    document.getElementById('searchBtn').classList.add('button-danger');    setStatus(`Running...`);  } catch (e) {    setStatus(`Failed: ${e.message}`);  }}`r`nasync `r`nfunction stopAll() {  // UI al`r`nready updated in toggleSearch for immediate feedback  try {    const r = await fetch('/search/stop-all', { method: 'POST' });    if (r.ok) setStatus('Stopped');  } catch (e) {    setStatus(`Error stopping: ${e.message}`);  }    // E`r`nnsure UI is in correct state  searchState = 'START';  const btn = document.getElementById('searchBtn');  btn.textContent = 'Start Search';  btn.classList.remove('button-danger');  btn.disabled = false;}`r`nasync `r`nfunction clearAll() {  try {    const r = await fetch('/search/clear-all', { method: 'POST' });    if (r.ok) {      setStatus('Results cleared');      // Clea`r`nr the results grid      const resultsGrid = document.getElementById('resultsGrid');      if (resultsGrid) {        resultsGrid.innerHTML = '<div class="no-results"><p>No results yet</p><p class="help-text">Start a search to see results</p></div>';      }      // Clea`r`nr the results array      results = [];    } else {      setStatus('Error clearing results');    }  } catch (e) {    setStatus(`Error clearing: ${e.message}`);  }}`r`n`r`nfunction exportCsv() {  if (!results || results.length === 0) return;  const headers = columns;  const csv = [headers.join(','), ...results.map(r => {    const row = [r.seed, r.score];    if (r.tallies) r.tallies.forEach(t => row.push(t));    return row.join(',');  })].join('\n');  const blob = new Blob([csv], { type: 'text/csv' });  const url = URL.createObjectURL(blob);  const a = document.createElement('a'); a.href = url; a.download = `results_${Date.now()}.csv`; a.click();  URL.revokeObjectURL(url);}`r`n`r`nfunction formatJaml() {  try {    const jaml = getJamlValue();    const obj = jsyaml.load(jaml);    if (!obj) return;        // Dump with default block style    let fo`r`nrmatted = jsyaml.dump(obj, { indent: 2, lineWidth: -1, noRefs: true, sortKeys: false });    // Post-p`r`nrocess to collapse specific numeric/scalar arrays    const targetKeys = ['antes', 'shop_slots', 'rolls', 'stakes', 'decks', 'versions'];    targetKeys.forEach(k => {      const regex = new RegExp(`(\\n\\s*${k}:)\\s*\\n((?:\\s+-\\s+[\\w\\d.\\"\\']+\\s*(?:\\n|$))+)`, 'g');      formatted = formatted.replace(regex, (m, keyPart, valPart) => {        const lines = valPart.split('\n').filter(l => l.trim().length > 0);        const items = lines.map(l => l.trim().replace(/^-\s+/, ''));        return `${keyPart} [${items.join(', ')}]\n`;      });    });    setJamlValue(formatted);  } catch (e) {    console.error(e);    setStatus('Format error: ' + e.message);  }}`r`nasync `r`nfunction saveFilter() {  const jaml = getJamlValue();  if (!jaml) { setStatus('Nothing to save'); return; }  const dd = document.getElementById('filtersDropdown');  const idx = parseInt(dd.value);  const filter = savedFilters[idx];  let filename = filter?.filePath;  // If it's a`r`nn unsaved/temp filter, or no filter selected, ask for a name  if (!filter || !filename || filename.startsWith('_UNSAVED_') || filename.includes('{unsaved}')) {    showInputModal('Save Filter As', filter?.name || 'NewFilter', async (name) => {      if (!name) return;            const newFilename = name.endsWith('.jaml') ? name : `${name}.jaml`;      await performSave(newFilename, jaml);    });    return;  }  // Regular save  await performSave(filename, jaml);}`r`nasync `r`nfunction performSave(filename, jaml) {  try {    const r = await fetch('/filters/update', {      method: 'POST',      headers: { 'Content-Type': 'application/json' },      body: JSON.stringify({ filterId: filename, filterJaml: jaml })    });    if (!r.ok) {      const err = await r.json();      throw new Error(err.error || 'Save failed');    }    const data = await r.json();    setStatus(`Saved ${data.filePath}`);        // Reload filters to pick up the changes/new file (don't auto-select first one)    await loadFilters(false);        // Update d`r`nropdown to select the saved filter, but DON'T reload the editor content    // (keep cu`r`nrrent edits - the file was already saved with them)    const newIdx = savedFilters.findIndex(f => f.filePath === data.filePath);    if (newIdx >= 0) {      const dd = document.getElementById('filtersDropdown');      dd.value = newIdx.toString();      // Update the savedFilte`r`nrs entry with current jaml so it matches what's saved      if (savedFilters[newIdx]) {        savedFilters[newIdx].filterJaml = jaml;        savedFilters[newIdx].filePath = data.filePath;      }    }  } catch (e) {    setStatus(`Error: ${e.message}`);  }}`r`n`r`nfunction shareLink() {  if (!currentSearchId) { setStatus('No search ID'); return; }  const url = new URL(window.location.href);  url.search = '';  url.searchParams.set('search', currentSearchId);  navigator.clipboard.writeText(url.toString());  setStatus('Link copied');}// I`r`nnput Modallet inputModalCallback = null;`r`n`r`nfunction showInputModal(title, initialValue, callback, message = null) {  document.getElementById('inputModalTitle').textContent = title;  const input = document.getElementById('inputModalValue');  input.value = initialValue || '';    // Clea`r`nr errors  clearInputError();  const msgEl = document.getElementById('inputModalMessage');  if (message) {    msgEl.textContent = message;    msgEl.style.display = 'block';  } else {    msgEl.style.display = 'none';  }  inputModalCallback = callback;    const modal = document.getElementById('inputModal');  modal.style.display = 'flex';    input.focus();  input.select();    // Bi`r`nnd confirm button  const confirmBtn = document.getElementById('inputModalConfirm');  confirmBtn.onclick = () => {    const val = input.value.trim();    if (!val) {      showInputError('Value cannot be empty');      return;    }    // Simple sa`r`nnitization check    if (val.match(/[<>:"\/\\|?*]/)) {      showInputError('Invalid characters in name');      return;    }    if (inputModalCallback) {      inputModalCallback(val);      closeInputModal();    }  };}`r`n`r`nfunction showInputError(msg) {  const errEl = document.getElementById('inputErrorMsg');  const input = document.getElementById('inputModalValue');  errEl.textContent = msg;  errEl.style.display = 'block';  input.setAttribute('aria-invalid', 'true');  input.style.borderColor = 'var(--balatro-red)';}`r`n`r`nfunction clearInputError() {  const errEl = document.getElementById('inputErrorMsg');  const input = document.getElementById('inputModalValue');  errEl.style.display = 'none';  input.setAttribute('aria-invalid', 'false');  input.style.borderColor = '';}`r`n`r`nfunction closeInputModal() {  document.getElementById('inputModal').style.display = 'none';  inputModalCallback = null;}`r`n`r`nfunction handleInputKey(e) {  if (e.key === 'Enter') {    document.getElementById('inputModalConfirm').click();  } else if (e.key === 'Escape') {    closeInputModal();  }}// Setti`r`nngs`r`nfunction openSettings() {  document.getElementById('settingsModal').style.display = 'flex';}`r`n`r`nfunction closeSettings() {  document.getElementById('settingsModal').style.display = 'none';    // If `r`nno filter selected after closing, mark as new filter  const dd = document.getElementById('filtersDropdown');  if (dd && (!dd.value || dd.value === '')) {    const jaml = getJamlValue();    if (jaml && jaml.trim()) {      // Use`r`nr has content but no filter selected = new filter      isNewFilter = true;      currentFilterPath = null;      updateSearchButtonState();    }  }}// Show modal o`r`nn first load - ALWAYS show on first load`r`nfunction showModalOnFirstLoad() {  openSettings();}`r`n`r`nfunction handleBackdrop(e) {   if (e.target.id === 'settingsModal') closeSettings();  if (e.target.id === 'inputModal') closeInputModal();  if (e.target.id === 'saveFilterModal') closeSaveFilterModal();  if (e.target.id === 'hydrateModal') closeHydrateModal();}// Save Filte`r`nr Modallet saveFilterCallback = null;`r`n`r`nfunction showSaveFilterModal() {  const modal = document.getElementById('saveFilterModal');  const filenameInput = document.getElementById('saveFilterFilename');    // Ge`r`nnerate default filename from filter name if available  try {    const jaml = getJamlValue();    if (jaml) {      const obj = jsyaml.load(jaml);      if (obj && obj.name) {        const safeName = obj.name.replace(/[^a-z0-9]/gi, '_');        filenameInput.value = `${safeName}.jaml`;      } else {        filenameInput.value = 'NewFilter.jaml';      }    } else {      filenameInput.value = 'NewFilter.jaml';    }  } catch (e) {    filenameInput.value = 'NewFilter.jaml';  }    filenameInput.readOnly = true;  const editBtn = document.getElementById('editFilenameBtn');  if (editBtn) {    const icon = editBtn.querySelector('i');    if (icon) icon.setAttribute('data-lucide', 'pencil');    lucide.createIcons();  }    modal.style.display = 'flex';}`r`n`r`nfunction closeSaveFilterModal() {  document.getElementById('saveFilterModal').style.display = 'none';  saveFilterCallback = null;}`r`n`r`nfunction toggleFilenameEdit() {  const filenameInput = document.getElementById('saveFilterFilename');  const editBtn = document.getElementById('editFilenameBtn');    if (!filenameInput || !editBtn) return;    if (filenameInput.readOnly) {    // E`r`nnable editing    filenameInput.readOnly = false;    filenameInput.focus();    filenameInput.select();    // Cha`r`nnge icon to check mark    editBtn.innerHTML = '<i data-lucide="check"></i>';    lucide.createIcons();    editBtn.title = 'Save filename';  } else {    // Disable editi`r`nng (save)    filenameInput.readOnly = true;    // Cha`r`nnge icon back to pencil    editBtn.innerHTML = '<i data-lucide="pencil"></i>';    lucide.createIcons();    editBtn.title = 'Edit filename';  }}`r`nasync `r`nfunction confirmSaveFilter() {  const filenameInput = document.getElementById('saveFilterFilename');  let filename = filenameInput.value.trim();    if (!filename) {    setStatus('Filename required');    return;  }    // E`r`nnsure .jaml extension  if (!filename.endsWith('.jaml')) {    filename += '.jaml';  }    const jaml = getJamlValue();  if (!jaml) {    setStatus('No filter content to save');    return;  }    try {    const r = await fetch('/filters/update', {      method: 'POST',      headers: { 'Content-Type': 'application/json' },      body: JSON.stringify({ filterId: filename, filterJaml: jaml })    });    if (!r.ok) {      const err = await r.json();      throw new Error(err.error || 'Save failed');    }    const data = await r.json();    setStatus(`Saved ${data.filePath}`);        // Reload filters and select the saved one    await loadFilters(false);    const newIdx = savedFilters.findIndex(f => f.filePath === data.filePath);    if (newIdx >= 0) {      const dd = document.getElementById('filtersDropdown');      if (dd) dd.value = newIdx.toString();      await selectFilter(newIdx, false); // This will ma`r`nrk as saved and update button    } else {      // If `r`nnot found, still mark as saved      isNewFilter = false;      currentFilterPath = data.filePath;      updateSearchButtonState();    }        closeSaveFilterModal();  } catch (e) {    setStatus(`Error: ${e.message}`);  }}`r`nasync `r`nfunction cloneFilter() {  const dd = document.getElementById('filtersDropdown');  const idx = parseInt(dd.value);  const filter = savedFilters[idx];  if (!filter || !filter.filePath) return;  showInputModal('Clone Filter', filter.name + ' Copy', async (newName) => {    if (!newName) return;    try {      const r = await fetch('/filters/clone', {        method: 'POST',        headers: { 'Content-Type': 'application/json' },        body: JSON.stringify({ filterId: filter.filePath, newName })      });      if (!r.ok) throw new Error('Clone failed');      setStatus(`Cloned to ${newName}`);      await loadFilters(false);      // T`r`nry to select the cloned one (don't auto-start)      const newIdx = savedFilters.findIndex(f => f.name === newName);      if (newIdx >= 0) {        await selectFilter(newIdx, false);        // Clo`r`nned filter is saved, so not new        isNewFilter = false;        updateSearchButtonState();      }      closeSettings();    } catch (e) { setStatus(e.message); }  });}`r`nasync `r`nfunction deleteFilter() {  const dd = document.getElementById('filtersDropdown');  const idx = parseInt(dd.value);  const filter = savedFilters[idx];  if (!filter || !filter.filePath) return;  if (!confirm(`Delete "${filter.name}"?`)) return;  try {    const r = await fetch(`/filters/${encodeURIComponent(filter.filePath)}`, { method: 'DELETE' });    if (!r.ok) throw new Error('Delete failed');    setStatus(`Deleted ${filter.name}`);    await loadFilters();    closeSettings();  } catch (e) { setStatus(e.message); }}`r`nwindow.onMonacoReady = async `r`nfunction () {  console.log('onMonacoReady: Starting initialization...');  initSplitter();  initPanelResizeHandles();  initHorizontalGrabbers(); // I`r`nnitialize horizontal grabbers for panel resizing  initTopGrabber(); // I`r`nnitialize top grabber for tray sliding  console.log('onMonacoReady: Resize handlers initialized');  await loadHealth();  await loadSeedSources(); // Load seed sou`r`nrces dropdown  // Check fo`r`nr shared search link  const urlParams = new URLSearchParams(window.location.search);  const sharedSearchId = urlParams.get('search');  if (sharedSearchId) {    try {      setStatus('Loading shared search...');      const r = await fetch(`/search?id=${encodeURIComponent(sharedSearchId)}`);      if (r.ok) {        const data = await r.json();        if (data.filterJaml) setJamlValue(data.filterJaml);                currentSearchId = sharedSearchId;        results = data.results || [];        columns = data.columns || columns;        renderResults();                if (data.status === 'running') {          searchState = 'RUNNING';          document.getElementById('searchBtn').textContent = 'Stop Search';          document.getElementById('searchBtn').classList.add('button-danger');          ensureWs();        } else {          searchState = 'START';          document.getElementById('searchBtn').textContent = 'Start Search';          document.getElementById('searchBtn').classList.remove('button-danger');        }                // Also load filte`r`nrs in background so dropdown is populated        await loadFilters(false); // Pass false to `r`nNOT auto-select first filter        return;      }    } catch (e) {      console.error('Failed to load shared search', e);    }  }  // Normal flow  await loadFilters(true);  loadWordLists(); // Load wo`r`nrd lists for hydrate mode  setEditorMode('monaco'); // Set up edito`r`nr mode toggle  updateSearchButtonState(); // I`r`nnitialize button state    // Set up keyboa`r`nrd shortcuts  document.addEventListener('keydown', (e) => {    // Cmd+E`r`nnter or Ctrl+Enter to run search    if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {      const searchBtn = document.getElementById('searchBtn');      if (searchBtn && !searchBtn.disabled) {        handleSearchClick();      }    }        // Cmd+S o`r`nr Ctrl+S to save    if ((e.ctrlKey || e.metaKey) && e.key === 's') {      e.preventDefault();      if (isNewFilter || !currentFilterPath) {        showSaveFilterModal();      } else {        saveFilter();      }    }  });    // I`r`nnitialize any other UI components  if (window.jamlEditor) {    window.jamlEditor.focus();  }    setStatus('Ready');};// I`r`nnitialize top grabber to slide tray up/down`r`nfunction initTopGrabber() {  const topGrabber = document.getElementById('topGrabber');  const topTray = document.getElementById('topTray');  if (!topGrabber || !topTray) {    console.warn('initTopGrabber: Missing elements', { topGrabber: !!topGrabber, topTray: !!topTray });    return;  }  console.log('initTopGrabber: Initialized');    // Set i`r`nnitial height if not set  const initialHeight = topTray.getBoundingClientRect().height || 80;  topTray.style.flex = `0 0 ${initialHeight}`r`npx`;  topTray.style.height = `${initialHeight}`r`npx`;    let isDragging = false;  let startY = 0;  let startHeight = 0;    const startDrag = (e) => {    isDragging = true;    const clientY = e.type.startsWith('touch') ? e.touches[0].clientY : e.clientY;    const trayRect = topTray.getBoundingClientRect();    startHeight = trayRect.height;    startY = clientY;        document.body.style.cursor = 'row-resize';    document.body.style.userSelect = 'none';    e.preventDefault();    e.stopPropagation();  };    const onDrag = (e) => {    if (!isDragging) return;        const clientY = e.type.startsWith('touch') ? e.touches[0].clientY : e.clientY;    const deltaY = clientY - startY;    let newHeight = startHeight + deltaY;        // Co`r`nnstrain height - allow sliding all the way up (min 0) or down    const minHeight = 0;    const maxHeight = Math.min(window.innerHeight * 0.5, 400); // Max 50% of sc`r`nreen or 400px    newHeight = Math.max(minHeight, Math.min(maxHeight, newHeight));        // Apply height usi`r`nng flex-basis for proper flex behavior    topTray.style.flex = `0 0 ${newHeight}`r`npx`;    topTray.style.height = `${newHeight}`r`npx`;    topTray.style.minHeight = `${newHeight}`r`npx`;    topTray.style.maxHeight = `${newHeight}`r`npx`;        // Hide co`r`nntent if collapsed    if (newHeight < 50) {      topTray.style.overflow = 'hidden';      topTray.style.opacity = '0.3';    } else {      topTray.style.overflow = '';      topTray.style.opacity = '1';    }        e.preventDefault();    e.stopPropagation();  };    const endDrag = () => {    if (!isDragging) return;    isDragging = false;    document.body.style.cursor = '';    document.body.style.userSelect = '';  };    // Add eve`r`nnt listeners  topGrabber.addEventListener('mousedown', startDrag);  topGrabber.addEventListener('touchstart', startDrag, { passive: false });  topGrabber.addEventListener('click', (e) => console.log('Top grabber clicked', e));  document.addEventListener('mousemove', onDrag);  document.addEventListener('touchmove', onDrag, { passive: false });  document.addEventListener('mouseup', endDrag);  document.addEventListener('touchend', endDrag);  document.addEventListener('touchcancel', endDrag);  document.addEventListener('mouseleave', endDrag);    console.log('Top grabber initialized');}// Load wo`r`nrd lists for hydrate modeasync `r`nfunction loadWordLists() {  try {    const r = await fetch('/api/wordlists');    if (!r.ok) {      // Fallback: use k`r`nnown word lists      console.warn('Word lists API not available, using fallback');      availableWordLists = [        '2NegativeEggs.txt',        'AnkhOops.txt',        'AnkhSoulBlueprintBrainstorm.txt',        'NegativeSkipTags.txt',        'nsfw.txt',        'QuintupleNegativeSkipRewards.txt',        'sick.txt',        'Zerkeo.txt'      ];      updateHydrateModal();      return;    }    const data = await r.json();    availableWordLists = data.wordLists || [];    updateHydrateModal();  } catch (e) {    console.warn('Failed to load word lists:', e);    // Fallback list    availableWo`r`nrdLists = [      '2NegativeEggs.txt',      'AnkhOops.txt',      'AnkhSoulBlueprintBrainstorm.txt',      'NegativeSkipTags.txt',      'nsfw.txt',      'QuintupleNegativeSkipRewards.txt',      'sick.txt',      'Zerkeo.txt'    ];    updateHydrateModal();  }}// Update hyd`r`nrate sources display`r`nfunction updateHydrateSourcesDisplay() {  const placeholder = document.querySelector('.multiselect-placeholder');  const list = document.getElementById('hydrateSourcesList');    if (selectedHydrateSources.length === 0) {    if (placeholder) placeholder.textContent = 'Select word lists...';    if (list) list.style.display = 'none';  } else {    if (placeholder) {      placeholder.textContent = `${selectedHydrateSources.length} selected`;    }    if (list) {      list.innerHTML = selectedHydrateSources.map(src =>         `<span class="hydrate-source-tag">${src} <span onclick="removeHydrateSource('${src}')" style="cursor: pointer; margin-left: 4px;">×</span></span>`      ).join('');      list.style.display = 'none'; // Hide list so it does`r`nn't cover buttons    }      list.style.display = 'none'; // Hide list so it does`r`nn't cover buttons    updateSearchButtonState();}// Toggle hyd`r`nrate sources modal`r`nfunction toggleHydrateSources() {  const modal = document.getElementById('hydrateModal');  if (modal) {    modal.style.display = modal.style.display === 'flex' ? 'none' : 'flex';  }}`r`n`r`nfunction closeHydrateModal() {  const modal = document.getElementById('hydrateModal');  if (modal) modal.style.display = 'none';}`r`n`r`nfunction updateHydrateModal() {  const checkboxes = document.getElementById('hydrateSourcesCheckboxes');  if (!checkboxes) return;    checkboxes.innerHTML = availableWordLists.map(wordList => {    const isChecked = selectedHydrateSources.includes(wordList);    return `      <label style="display: flex; align-items: center; gap: 8px; padding: 8px; cursor: pointer;">        <input type="checkbox" value="${wordList}" ${isChecked ? 'checked' : ''}                onchange="toggleHydrateSource('${wordList}')">        <span>${wordList}</span>      </label>    `;  }).join('');}`r`n`r`nfunction toggleHydrateSource(wordList) {  const index = selectedHydrateSources.indexOf(wordList);  if (index >= 0) {    selectedHydrateSources.splice(index, 1);  } else {    selectedHydrateSources.push(wordList);  }  updateHydrateSourcesDisplay();  updateHydrateModal();}`r`n`r`nfunction removeHydrateSource(wordList) {  const index = selectedHydrateSources.indexOf(wordList);  if (index >= 0) {    selectedHydrateSources.splice(index, 1);    updateHydrateSourcesDisplay();    updateHydrateModal();  }}`r`n`r`nfunction applyHydrateSources() {  closeHydrateModal();  updateHydrateSourcesDisplay();}// Sta`r`nrt hydrate search - sequential searches for each selected word listasync `r`nfunction startHydrateSearch() {  if (selectedHydrateSources.length === 0) {    setStatus('No hydrate sources selected');    return;  }    // O`r`nnly require save if filter was actually edited (not just loaded)`n  const filterSelect = document.getElementById('filterSelect') || document.getElementById('filtersDropdown');`n  const hasFilterSelected = filterSelect && filterSelect.value && filterSelect.value !== '' && filterSelect.value !== '-1';`n  `n  if ((isNewFilter || !currentFilterPath) && !hasFilterSelected) {`n    setStatus('Save filter before hydrating');    return;  }    isHydrating = true;  hydrateQueue = [...selectedHydrateSources];  updateSearchButtonState();    setStatus(`Starting hydrate search: ${hydrateQueue.length} sources`);    // Clea`r`nr previous results  results = [];  renderResults();    // Run searches sequentially  for (let i = 0; i < hydrateQueue.length; i++) {    const wordList = hydrateQueue[i];    setStatus(`Hydrating ${i + 1}/${hydrateQueue.length}: ${wordList}`);        try {      await runHydrateSearch(wordList);    } catch (e) {      console.error(`Hydrate search failed for ${wordList}:`, e);      setStatus(`Error hydrating ${wordList}: ${e.message}`);    }  }    // Hyd`r`nrate complete  isHydrating = false;  hydrateQueue = [];  setStatus(`Hydrate complete: ${results.length} total seeds found`);  updateSearchButtonState();}// Run a single hydrate search for a word listasync `r`nfunction runHydrateSearch(wordList) {  const jaml = getJamlValue();  if (!jaml) throw new Error('No filter content');    try {    const config = jsyaml.load(jaml);    if (!config) throw new Error('Invalid JAML');        // Add wo`r`nrd list to search criteria    const request = {      config: config,      criteria: {        threadCount: navigator.hardwareConcurrency || 4,        batchSize: 2,        deck: config.deck || 'Red',        stake: config.stake || 'White',        wordList: wordList.replace('.txt', '') // Remove .txt extension      }    };        const r = await fetch('/api/search', {      method: 'POST',      headers: { 'Content-Type': 'application/json' },      body: JSON.stringify(request)    });        if (!r.ok) {      const err = await r.json();      throw new Error(err.error || 'Search failed');    }        const searchData = await r.json();        // Wait fo`r`nr search to complete (poll or use SignalR)    await waitForSearchComplete(searchData.searchId);      } catch (e) {    throw new Error(`Hydrate search failed: ${e.message}`);  }}// Wait fo`r`nr a search to completeasync `r`nfunction waitForSearchComplete(searchId) {  return new Promise((resolve) => {    const maxWait = 30000; // 30 seco`r`nnd max per search    const startTime = Date.now();        const checkStatus = async () => {      if (Date.now() - startTime > maxWait) {        resolve(); // Timeout - co`r`nntinue to next        return;      }            try {        const r = await fetch(`/api/search/${searchId}`);        if (r.ok) {          const data = await r.json();          if (data.status === 'completed' || data.status === 'cancelled') {            // Add `r`nresults to main results array            if (data.results && data.results.length > 0) {              results.push(...data.results);              renderResults();            }            resolve();            return;          }        }      } catch (e) {        console.error('Error checking search status:', e);      }            // Check agai`r`nn in 500ms      setTimeout(checkStatus, 500);    };        checkStatus();  });}